import pandas as pd,numpy as np,pickle
from sklearn.model_selection import KFold
from scipy.spatial.distance import cdist
tr=pd.read_csv('/work/b3_htsteel_pareto_train.csv');po=pd.read_csv('/work/b3_htsteel_pareto_pool.csv');xx=tr.iloc[:,:-2];pp=po[xx.columns];y=tr.iloc[:,-2:].values
folds=list(KFold(5,shuffle=True,random_state=81).split(xx));
results=[];cvs={};preds={}
for log in [False,True]:
 x=xx.copy();p=pp.copy()
 if log:
  for c in xx.columns:
   if 'time' in c or 'cooling' in c: x[c]=np.log1p(x[c]);p[c]=np.log1p(p[c])
 s=x.std().replace(0,1);x=(x/s).values;p=(p/s).values
 for proc in [.25,.5,1,2,4]:
  scal=np.ones(x.shape[1]);scal[16:]*=proc
  d=cdist(x*scal,x*scal);dp=cdist(p*scal,x*scal)
  for power in [1,2,3,4,6]:
   for k in [1,3,5,10,20]:
    cv=np.zeros_like(y)
    for a,b in folds:
     ds=d[b][:,a]; ii=np.argsort(ds,axis=1)[:,:k]; dd=np.take_along_axis(ds,ii,axis=1); w=1/(dd+1e-5)**power
     w/=w.sum(axis=1,keepdims=True);cv[b]=np.sum(y[a[ii]]*w[:,:,None],axis=1)
    ii=np.argsort(dp,axis=1)[:,:k];dd=np.take_along_axis(dp,ii,axis=1);w=1/(dd+1e-5)**power;w/=w.sum(axis=1,keepdims=True)
    pred=np.sum(y[ii]*w[:,:,None],axis=1)
    rmse=np.sqrt(((cv-y)**2).mean(axis=0)); mae=abs(cv-y).mean(axis=0)
    key=f'{log}_{proc}_{power}_{k}'
    results.append([key,*rmse,*mae, np.mean((rmse/y.std(axis=0))**2)])
    cvs[key]=cv;preds[key]=pred
r=pd.DataFrame(results,columns=['key','rmseY','rmseE','maeY','maeE','score'])
print(r.nsmallest(20,'score').round(3).to_string(index=False))
print('bestY',r.nsmallest(10,'rmseY').round(3).to_string(index=False));print('bestE',r.nsmallest(10,'rmseE').round(3).to_string(index=False))
pickle.dump((r,cvs,preds),open('/tmp/steel_knn.pkl','wb'))

import pandas as pd,numpy as np,pickle,time
from sklearn.model_selection import KFold
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from catboost import CatBoostRegressor
tr=pd.read_csv('/work/b3_htsteel_pareto_train.csv');po=pd.read_csv('/work/b3_htsteel_pareto_pool.csv');X=tr.iloc[:,:-2];P=po[X.columns];y=tr.iloc[:,-2:].values
folds=list(KFold(5,shuffle=True,random_state=81).split(X));preds={};cvs={}
for feat in ['log','less']:
 x=X.copy();p=P.copy()
 if feat=='less':
  x=x.drop(columns=['Fe','P','S','B']);p=p[x.columns]
 for c in x.columns:
  if 'time' in c or 'cooling' in c:
   x[c]=np.log1p(x[c]);p[c]=np.log1p(p[c])
 for typ in ['cat4','cat6','et','rf']:
  cv=np.zeros_like(y);pr=np.zeros((len(P),2));t=time.time()
  for j in range(2):
   if typ.startswith('cat'):
    m=CatBoostRegressor(iterations=1800,depth=int(typ[-1]),learning_rate=.03,l2_leaf_reg=4,verbose=False,thread_count=2,allow_writing_files=False,random_seed=21)
   elif typ=='et':m=ExtraTreesRegressor(n_estimators=900,max_features=.9,n_jobs=2,random_state=21)
   else:m=RandomForestRegressor(n_estimators=900,max_features=.9,n_jobs=2,random_state=21)
   for a,b in folds:
    m.fit(x.iloc[a],y[a,j]);cv[b,j]=m.predict(x.iloc[b])
   m.fit(x,y[:,j]);pr[:,j]=m.predict(p)
  key=feat+typ;preds[key]=pr;cvs[key]=cv
  print(key,'RMSE',np.sqrt(np.mean((cv-y)**2,axis=0)),'MAE',np.mean(abs(cv-y),axis=0),'time',time.time()-t,flush=True)
pickle.dump((preds,cvs),open('/tmp/steel_more.pkl','wb'))
r=pd.DataFrame({'id':po.candidate_id})
for k,p in preds.items():r[k+'_Y']=p[:,0];r[k+'_E']=p[:,1]
print(r.round(1).to_string(index=False))

